from fractions import Fraction as F
from decimal import Decimal, localcontext

# Exact arithmetic in Q(sqrt(39)).
class Q:
    def __init__(self, a=0, b=0):
        self.a, self.b = F(a), F(b)

    @staticmethod
    def coerce(v):
        return v if isinstance(v, Q) else Q(v)

    def __add__(self, other):
        other = self.coerce(other)
        return Q(self.a + other.a, self.b + other.b)

    __radd__ = __add__

    def __neg__(self):
        return Q(-self.a, -self.b)

    def __sub__(self, other):
        return self + (-self.coerce(other))

    def __rsub__(self, other):
        return self.coerce(other) - self

    def __mul__(self, other):
        other = self.coerce(other)
        return Q(self.a * other.a + 39 * self.b * other.b,
                 self.a * other.b + self.b * other.a)

    __rmul__ = __mul__

    def __truediv__(self, other):
        other = self.coerce(other)
        norm = other.a**2 - 39 * other.b**2
        if norm == 0:
            raise ZeroDivisionError
        return self * Q(other.a / norm, -other.b / norm)

    def __eq__(self, other):
        other = self.coerce(other)
        return self.a == other.a and self.b == other.b

    def sign(self):
        a, b = self.a, self.b
        if b == 0:
            return (a > 0) - (a < 0)
        if a == 0:
            return (b > 0) - (b < 0)
        if a > 0 and b > 0:
            return 1
        if a < 0 and b < 0:
            return -1
        comparison = a*a - 39*b*b
        if a > 0:
            return (comparison > 0) - (comparison < 0)
        return (comparison < 0) - (comparison > 0)

    def __str__(self):
        if not self.b:
            return str(self.a)
        return f"({self.a}) + ({self.b})*sqrt(39)"

    def decimal(self):
        with localcontext() as ctx:
            ctx.prec = 40
            return (Decimal(self.a.numerator) / Decimal(self.a.denominator)
                    + Decimal(self.b.numerator) / Decimal(self.b.denominator)
                    * Decimal(39).sqrt())


# Verify the symmetric identities using exact polynomial arithmetic.
def add(*polys):
    result = {}
    for p in polys:
        for m, c in p.items():
            result[m] = result.get(m, 0) + c
    return {m: c for m, c in result.items() if c}

def scale(p, c):
    return {m: c*v for m, v in p.items() if c*v}

def mul(p, q):
    result = {}
    for u, a in p.items():
        for v, b in q.items():
            m = tuple(u[i] + v[i] for i in range(3))
            result[m] = result.get(m, 0) + a*b
    return {m: c for m, c in result.items() if c}

X = {(1, 0, 0): 1}
Y = {(0, 1, 0): 1}
Z = {(0, 0, 1): 1}
S = add(X, Y, Z)
T = add(mul(X, Y), mul(Y, Z), mul(Z, X))
R = mul(mul(X, Y), Z)
D = mul(mul(add(X, Y), add(X, Z)), add(Y, Z))

B = add(
    mul(mul(X, Y), mul(add(X, Z), add(Y, Z))),
    mul(mul(X, Z), mul(add(X, Y), add(Y, Z))),
    mul(mul(Y, Z), mul(add(X, Y), add(X, Z)))
)
assert D == add(mul(S, T), scale(R, -1))
assert B == add(mul(T, T), mul(S, R))

# Hence E = 18 - 2*(196 + 9*r)/(126 - r), r = xyz.
# Its derivative with respect to r is -2660/(126-r)^2 < 0.
assert -2 * (9*126 + 196) == -2660

print("Verified exact identity: E = 18 - 2*(196 + 9*r)/(126 - r).")
print("E is strictly decreasing in r = xyz.")

# Complete maximization of r on the compact nonnegative feasible set:
# At the boundary r = 0; (0,2,7) is feasible.
# Interior constraint gradients are independent: dependence would force
# x=y=z=3, contradicting xy+yz+zx=14.
# Lagrange equations for r imply
# (y-x)(z-mu)=(z-y)(x-mu)=(x-z)(y-mu)=0.
# Three distinct coordinates are impossible, so two must be equal.
# Writing those coordinates as a gives b=9-2a and
# a^2+2ab=14, i.e. 3a^2-18a+14=0.
candidates = []
for sign in (-1, 1):
    a = Q(3, F(sign, 3))
    b = 9 - 2*a
    assert 3*a*a - 18*a + 14 == 0
    if a.sign() > 0 and b.sign() > 0:
        assert 2*a + b == 9
        assert a*a + 2*a*b == 14
        candidates.append((a*a*b, a, a, b))

assert len(candidates) == 1
rmax, x, y, z = candidates[0]
assert rmax.sign() > 0  # Beats every boundary candidate.
assert rmax == Q(-12, F(26, 9))
assert (126 - rmax).sign() > 0

minimum = 18 - 2*(196 + 9*rmax)/(126 - rmax)
direct = ((x*x + y*y)/(x+y)
          + (x*x + z*z)/(x+z)
          + (y*y + z*z)/(y+z))
assert direct == minimum

print("Complete candidate enumeration: boundary product 0;")
print("the only positive interior candidate, up to permutation, is:")
print("x = y =", x)
print("z =", z)
print("Maximum xyz =", rmax)
print("Minimum E =", minimum)
print("Minimum E (decimal) =", minimum.decimal())

# Test the submitted common-denominator simplification at the minimizer.
denominator = (x+y)*(x+z)*(y+z)
claimed_numerator = 2*(x*x*x + y*y*y + z*z*z) + 3*x*y*z*(x+y+z)
actual_numerator = direct * denominator
assert claimed_numerator != actual_numerator
print("Submitted numerator minus actual numerator =",
      claimed_numerator - actual_numerator)
print("The submission gives no minimum and contains a false algebraic identity.")
print("CHECK FAIL")
